<?php
require 'config/auth.php';require 'config/db.php';require_permission('report.export');
$year=(int)($_GET['year']??fiscal_year_for_date());$unitId=is_admin()?(int)($_GET['unit_id']??0):current_unit_id();
$units=is_admin()?$conn->query('SELECT id,unit_code,unit_name FROM units ORDER BY unit_code')->fetch_all(MYSQLI_ASSOC):[];
$sql="SELECT ca.id,ca.budget_code,ca.item_name,ca.status,ca.received_amount,u.unit_code,
COALESCE(SUM(CASE WHEN e.entry_type='increase' THEN e.amount ELSE 0 END),0) extra,
COALESCE(SUM(CASE WHEN e.entry_type='payment' THEN e.amount ELSE 0 END),0) paid,
COALESCE(SUM(CASE WHEN e.entry_type IN ('transfer_out','return_army','remittance') THEN e.amount ELSE 0 END),0) outgoing
FROM control_accounts ca JOIN units u ON u.id=ca.unit_id LEFT JOIN active_control_entries e ON e.control_account_id=ca.id WHERE ca.fiscal_year=?".($unitId>0?' AND ca.unit_id=?':'').' GROUP BY ca.id ORDER BY ca.id DESC';
$stmt=$conn->prepare($sql);$unitId>0?$stmt->bind_param('ii',$year,$unitId):$stmt->bind_param('i',$year);$stmt->execute();$rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$ready=0;foreach($rows as $r)if(in_array($r['status'],['ready','exported'],true))$ready++;
?>
<!doctype html><html lang="th"><head><meta name="viewport" content="width=device-width, initial-scale=1"><meta charset="utf-8"><title>ส่งออกรายงาน</title><link rel="stylesheet" href="assets/css/style.css?v=<?=filemtime(__DIR__.'/assets/css/style.css')?>"></head><body><?php require 'template/nav.php';?><main class="container"><section class="panel"><h1 class="page-title">ส่งออกรายงาน</h1><p class="page-subtitle">เลือกปีและหน่วย ตรวจบัญชีคุมงบประมาณ ก่อนสร้างรายงาน</p><form method="get" class="toolbar"><label>ปีงบประมาณ</label><input type="number" name="year" value="<?=$year?>" style="width:150px"><?php if(is_admin()):?><label>หน่วย</label><select name="unit_id" style="width:300px"><option value="0">ทุกหน่วย</option><?php foreach($units as $u):?><option value="<?=(int)$u['id']?>" <?=$unitId===(int)$u['id']?'selected':''?>><?=htmlspecialchars($u['unit_code'].' '.$u['unit_name'])?></option><?php endforeach;?></select><?php endif;?><button class="btn btn-primary">โหลดข้อมูล</button><a class="btn btn-outline" href="report_review.php?year=<?=$year?>&unit_id=<?=$unitId?>">ตรวจสอบ/แก้ไข</a></form><p>บัญชีที่ส่งออกได้: <strong><?=$ready?></strong> จาก <?=count($rows)?> บัญชี</p><?php if($ready):?><div class="toolbar"><a class="btn btn-success" href="exports/export_report_500_200.php?year=<?=$year?>&unit_id=<?=$unitId?>">ส่งออก ทบ.500-200</a><a class="btn btn-success" href="exports/export_report_500_153_154.php?year=<?=$year?>&unit_id=<?=$unitId?>">ส่งออก ทบ.500-153/154</a></div><?php else:?><div class="alert alert-danger">ยังไม่มีรายการพร้อมส่งออก กรุณาเปลี่ยนสถานะในหน้าตรวจสอบก่อน</div><?php endif;?></section><section class="panel"><div class="table-wrap"><table><tr><th>หน่วย</th><th>รหัสงบประมาณ</th><th>รายการ</th><th class="text-right">รับรวม</th><th class="text-right">ตัดจ่าย</th><th class="text-right">คงเหลือ</th><th>สถานะ</th></tr><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['unit_code'])?></td><td><a href="control_account_detail.php?id=<?=(int)$r['id']?>"><?=htmlspecialchars($r['budget_code'])?></a></td><td><?=htmlspecialchars($r['item_name'])?></td><td class="text-right"><?=number_format((float)$r['received_amount']+(float)$r['extra'],2)?></td><td class="text-right"><?=number_format((float)$r['paid'],2)?></td><td class="text-right"><?=number_format((float)$r['received_amount']+(float)$r['extra']-(float)$r['paid']-(float)$r['outgoing'],2)?></td><td><?=htmlspecialchars($r['status'])?></td></tr><?php endforeach;?></table></div></section></main></body></html>
